            self.adj[v].add(int(u))
        # Store parent pointers from BFS from root (node 1)
        self.parent: Dict[int, int] = {}
        self.level: Dict[int, int] = {}
        self._bfs_root()

    def _bfs_root(self):
        queue = [(1, 0)]
        visited = {1}
        self.parent[1] = 0  # Root has no parent
        self.level[1] = 0
        while queue:
            u, _ = queue.pop(0)
            for v in self.adj[u]:
                if v not in visited:
                    visited.add(v)
                    self.parent[v] = u
                    self.level[v] = self.level[u] + 1
                    queue.append((v, 0))

    def _get_responses(self, query: str) -> Optional[str]:
        if self.idx < len(self.responses):
            resp = self.responses[self.idx]
            self.idx += 1
            return resp
        return None

