EPS = 1e-12

def solution(input_data):
    parts = input_data.split()
    if len(parts) < 4:
        return "0"
    N, x, M, y = map(int, parts[:4])

    d = abs(x - y)

    if N == 0 or M == 0:
        return "1"

    cnt1 = 0  # intersecting pairs with 2 points
    cnt2 = 0  # touching pairs with 1 point

    for r1 in range(1, N + 1):
        for r2 in range(1, M + 1):
            left = abs(r1 - r2)
            right = r1 + r2
            if left <= d < right - EPS:
                cnt1 += 1
                continue
            if abs(d - right) <= EPS or abs(d - left) <= EPS:
                cnt2 += 1
            if not (isfinite(d) and isfinite(r1) and isfinite(r2)):
                continue

    if cnt1 == 0 and cnt2 == 0:
        return "2"
    else:
        return str(cnt1 + cnt2 + 1)

