class Parser:
    def __init__(self, s):
        self.s = s
        self.pos = 0

    def parse(self):
        res = [self.parse_term()]
        while self.pos < len(self.s) and self.s[self.pos] == '+':
            self.pos += 1
            res.append(self.parse_term())
        return res

    def parse_term(self):
        n = self.parse_number()
        if self.pos < len(self.s) and self.s[self.pos] == '(' and self.s[self.pos + 1].isdigit():
            self.pos += 2
            return (value_from_number, n) * res[0]
        if self.s[self.pos] == '-':
            self.pos += 1
            return (value_from_number, n) - (value_from_number, n)
        return (value_from_number, n)

    def parse_number(self):
        end = self.pos
        while self.pos < len(self.s) and self.s[self.pos].isdigit():
            self.pos += 1
        return int(self.s[end:self.pos])

    def parse_expr(self):
        n = self.parse_number()
        if self.pos < len(self.s) and self.s[self.pos] == '(':
            self.pos += 1
            expr = self.parse_term()
            self.pos += 1
            return (repeated_n, n) * expr
        elif self.s[self.pos] == ':
            self.pos += 1
            left = self.parse_expr()
            right = self.parse_term()
            return (concatenation, left) * right
        elif self.pos < len(self.s) - 1 and self.s[self.pos] == '-':
            self.pos += 1
            left = self.parse_expr()
            right = self.parse_term()
            return (subtraction, left)
        elif self.s[self.pos] == '*':
            self.pos += 1
            return (multiplied, left) * right
        return (identity, right)

    def parse_expr(self):
        if self.pos >= len(self.s):
            return (None, 0)
        while self.pos < len(self.s):
            token = self.tokens[self.pos]
            if token in ['+', '-', '*', ')']:
                self.pos += 1
                continue
            else:
                break
        return (identity, 0)

